377	/// Successful invocation: exit code 0, empty stderr, one valid record whose
378	/// fields/key-id/version match the inputs and whose tag equals the golden
379	/// value computed independently of this implementation.
380	fn expect_signed_record(
381	    label: &str,
382	    key: &str,
383	    key_id: &str,
384	    version: &str,
385	    fields: &[&str],
386	    golden_tag: &str,
387	) -> Record {
388	    let out = run_sign(key, key_id, version, fields);
389	    assert_eq!(
390	        out.status.code(),
391	        Some(0),
392	        "{label}: expected exit 0, got {:?}, stderr={:?}",
393	        out.status.code(),
394	        String::from_utf8_lossy(&out.stderr)
395	    );
396	    assert!(
397	        out.stderr.is_empty(),
398	        "{label}: stderr must be empty, got {:?}",
399	        String::from_utf8_lossy(&out.stderr)
400	    );
401	
402	    let rec = parse_single_record(&out.stdout);
403	    assert_eq!(rec.tag, golden_tag, "{label}: tag mismatch");
404	    assert_eq!(rec.key_id, key_id, "{label}: key_id mismatch");
405	    assert_eq!(
406	        rec.key_version,
407	        version.parse::<i64>().unwrap(),
408	        "{label}: key_version mismatch"
409	    );
410	    assert_eq!(
411	        rec.fields,
412	        fields.iter().map(|s| s.to_string()).collect::<Vec<_>>(),
413	        "{label}: parsed fields must be character-identical to the inputs"
414	    );
415	
416	    // The raw key is used only for the MAC: it must never appear as a value
417	    // anywhere in the record (compared as a whole string, not a substring, so
418	    // short keys cannot clash with random fragments of the 64-char tag).
419	    let needle = key.to_lowercase();
420	    let mut strings = Vec::new();
421	    rec.raw.strings(&mut strings);
422	    assert!(
423	        strings.iter().all(|s| s.to_lowercase() != needle),
424	        "{label}: raw key material must not be part of the record"
425	    );
426	    rec
427	}
