    );
    assert_ne!(ab.fields, ba.fields);
    assert_ne!(ab.tag, ba.tag);

    let xyx = expect_signed_record(
        "xyx",
        "00ff", "id", "1", &["x", "y", "x"],
        "7abf79d29bbc9944d3b5712ff5a137a057700810ecb57694243c86a5a7532358",
    );
    let xxy = expect_signed_record(
        "xxy",
